  ('4d9f0976-ddca-5841-a412-a867e3481add', 'so-ak4-kartan-1', 'SO / Historia / Samhällskunskap', 'ak4', 'Sveriges landskap och kartan', 'Landsdelar och landskap', 'Sveriges landsdelar och landskap, och några rekord på kartan.', 1, 'vanlig', null),
  ('08e04fd5-e39d-59b6-9533-c7b6cbf37a15', 'so-ak4-kartan-2', 'SO / Historia / Samhällskunskap', 'ak4', 'Sveriges landskap och kartan', 'Kartan och väderstrecken', 'Väderstreck, skala och teckenförklaring.', 2, 'vanlig', null),
