  ('7982789c-95c4-57b9-87e7-49e04f5857fb', '5733d615-e58e-52b9-96e6-41a28aac6d58', 7, 'ordna', 'Ordna divisionerna efter hur stor resten blir, minst rest först.', null, '["13 / 4","20 / 6","17 / 7","14 / 5"]'::jsonb, '13 / 4 = 3 rest 1, 20 / 6 = 3 rest 2, 17 / 7 = 2 rest 3 och 14 / 5 = 2 rest 4.'),
  ('ed002cc4-617b-532d-9f9e-a33ba60ee1f9', '5733d615-e58e-52b9-96e6-41a28aac6d58', 8, 'val', 'Vilken division går jämnt ut, utan rest?', '["36 / 5","42 / 8","45 / 9","50 / 7"]'::jsonb, '2'::jsonb, '9 · 5 = 45, så 45 / 9 = 5 och ingenting blir över.'),
  ('79fdaf3b-0886-59b8-ae6c-61041ad27044', '552faa3f-ded0-5fc1-be92-9ce7371178f4', 1, 'skriv', 'Vad är 80 / 4?', null, '["20"]'::jsonb, '8 / 4 = 2, och 80 är tio gånger så mycket som 8. Därför är 80 / 4 = 20.'),
  ('4cceac20-49ff-5b5f-9b0a-fedd606a8528', '552faa3f-ded0-5fc1-be92-9ce7371178f4', 2, 'val', 'Vad är 96 / 3?', '["32","33","30","23"]'::jsonb, '0'::jsonb, 'Dela upp 96 i 90 och 6: 90 / 3 = 30 och 6 / 3 = 2. 30 + 2 = 32.'),
  ('8d46aa52-521e-54c3-a484-c720bdb700d4', '552faa3f-ded0-5fc1-be92-9ce7371178f4', 3, 'skriv', 'Vad är 450 / 5?', null, '["90"]'::jsonb, '5 · 90 = 450. Därför är 450 / 5 = 90.'),
  ('35536a23-08e7-5abd-b51b-ed9bbbebd49e', '552faa3f-ded0-5fc1-be92-9ce7371178f4', 4, 'val', 'Fyra kompisar delar lika på 100 kr. Hur mycket får var och en?', '["25 kr","40 kr","20 kr","30 kr"]'::jsonb, '0'::jsonb, '4 · 25 = 100. Var och en får 25 kr.'),
  ('b6a47716-7f6b-5ce2-ba97-a81009c14f23', '552faa3f-ded0-5fc1-be92-9ce7371178f4', 5, 'skriv', '72 elever delas in i lag med 6 elever i varje. Hur många lag blir det?', null, '["12"]'::jsonb, '6 · 12 = 72. Det blir 12 lag.'),
  ('562ae3cd-06e2-5714-900c-dc2a8444d702', '552faa3f-ded0-5fc1-be92-9ce7371178f4', 6, 'val', 'Vilken division har samma svar som 60 / 3?', '["40 / 2","60 / 2","30 / 3"]'::jsonb, '0'::jsonb, '60 / 3 = 20 och 40 / 2 = 20. Men 60 / 2 = 30 och 30 / 3 = 10.'),
