  ('ee8b3552-af23-5636-bf18-cdbc22cabfe8', '0d2c724c-dea3-5ed4-a218-f3ff7e3ffadb', 2, 'val', 'Vad är 5 − 1,25?', '["3,75","4,25","4,75","3,25"]'::jsonb, '0'::jsonb, '5 − 1 = 4, och 4 − 0,25 = 3,75.'),
  ('819cc9f2-8827-5e7a-b951-b75d3ce43465', '0d2c724c-dea3-5ed4-a218-f3ff7e3ffadb', 3, 'skriv', 'Vad är 0,6 · 4?', null, '["2,4"]'::jsonb, '6 tiondelar fyra gånger är 24 tiondelar. Det är 2,4.'),
